package lk.repairdesk.api.exception; import org.springframework.http.*; import org.springframework.web.bind.MethodArgumentNotValidException; import org.springframework.web.bind.annotation.*; import java.time.Instant; import java.util.*; @RestControllerAdvice public class ApiExceptionHandler { record ErrorResponse(Instant timestamp,int status,String error,String message,Map<String,String> fieldErrors){} @ExceptionHandler(ResourceNotFoundException.class) ResponseEntity<ErrorResponse> notFound(ResourceNotFoundException e){return build(HttpStatus.NOT_FOUND,e.getMessage(),Map.of());} @ExceptionHandler(IllegalArgumentException.class) ResponseEntity<ErrorResponse> bad(IllegalArgumentException e){return build(HttpStatus.BAD_REQUEST,e.getMessage(),Map.of());} @ExceptionHandler(MethodArgumentNotValidException.class) ResponseEntity<ErrorResponse> validation(MethodArgumentNotValidException e){Map<String,String> m=new LinkedHashMap<>();e.getBindingResult().getFieldErrors().forEach(x->m.putIfAbsent(x.getField(),x.getDefaultMessage()));return build(HttpStatus.BAD_REQUEST,"Validation failed",m);} private ResponseEntity<ErrorResponse> build(HttpStatus s,String m,Map<String,String> f){return ResponseEntity.status(s).body(new ErrorResponse(Instant.now(),s.value(),s.getReasonPhrase(),m,f));} }